  root.addView(ReviewUi.text(this,f("실제 추적 → 측정 가능 여부 → 차이 확인 → 결과 공유","Track → validate measurement → compare → share","Śledź → sprawdź pomiar → porównaj → udostępnij","Відстежте → перевірте вимірювання → порівняйте → поділіться"),17,ReviewUi.MUTED));
