  start=ReviewUi.button(this,f("▶ 측정형 통합검사 시작","▶ Start measured inspection","▶ Uruchom kontrolę pomiarową","▶ Почати вимірювальну перевірку"));root.addView(start);start.setOnClickListener(v->run());
